// PacifidlogTown_House3 (zone 418): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0647_room_PacifidlogTown_House3.txt
#include "asm/field_script.inc"
#include "hoenn.h"  // ch6
#include "hoenn_story.inc"  // ch6

    ScriptEntry Script_1
    ScriptEntry Script_2
    ScriptEntry Story_H3_Trader   // 3: object 2 (the trader)  // story:
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    ActorSetEyeToEye
    ParentActorMsg MSGFILE_SCRIPT, 0, 0, 0
    LastKeyWait
    ActorMsgClose
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt

Script_2:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 1, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch12, ch6 agent: Sapphire data/maps/PacifidlogTown_House3/scripts.inc; generators keep everything
// from this line on). The trader (data/story/ch12.json, uid 2): Sapphire's in-game trade 2, her Corsola "Coroso" for a
// Bellossom, on Black 2's own in-game trade 26 (b2tools/patches/trades.py; names on lines 52/53 of system text 37,
// src/text/overrides.json), written like chapter Ch1's Rustboro trade (1170_room_RustboroCity_House1.s).
// Text lines 2-6 of the text file.
#define T_WILLING 2
#define T_DISAPPOINTED 3
#define T_NOTMON 4
#define T_FLUFFY 5
#define T_FRIENDS 6
#define H3_TRADE 26                                 // Black 2 in-game trade 26
#define H3_SLOT 0x8020                              // party slot picked
#define H3_OK 0x8021                                // 1 = a Pokémon was picked
#define H3_CHECK 0x8022                             // FieldTradeCheck: 0 = the wanted species

Story_H3_Trader:                                    // PacifidlogTown_House3_EventScript_Trader (lock, faceplayer)
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_PACIFIDLOG_NPC_TRADE_COMPLETED, L_H3_Completed
    h_bufferspeciesname 1, SPECIES_BELLOSSOM        // GetInGameTradeSpeciesInfo: STR_VAR_1 the wanted species, STR_VAR_2
    FieldTradeGetSpecies HLIB_TMP, H3_TRADE         //   the offered one (read from the trade)
    h_bufferspeciesname 2, HLIB_TMP
    h_yesno T_WILLING, HLIB_TMP                     // Hello, Trainer. Would you do me a favor and trade Pokémon with me? ...
    h_goto_if_no HLIB_TMP, L_H3_Decline
    MsgWinCloseAll
    WorkSetConst H3_SLOT, 0
    WorkSetConst H3_OK, 0
    CallPokeSelect 0, H3_OK, H3_SLOT, 0             // SelectMonForNPCTrade
    h_goto_if_ne H3_OK, 1, L_H3_Decline             // (none picked: Sapphire 0x8004 = 255)
    WorkSetConst H3_CHECK, 0
    FieldTradeCheck H3_CHECK, H3_TRADE, H3_SLOT     // GetTradeSpecies + compare with the wanted species
    h_goto_if_ne H3_CHECK, 0, L_H3_NotRequested
    FieldTradeStart H3_TRADE, H3_SLOT               // CreateInGameTradePokemon + DoInGameTradeScene
    h_msgbox T_FLUFFY                               // Wow! This Bellossom is so fluffy!
    h_setflag FLAG_PACIFIDLOG_NPC_TRADE_COMPLETED
    VMJump L_H3_Release
L_H3_Decline:
    h_msgbox T_DISAPPOINTED                         // I'm a little disappointed...
    VMJump L_H3_Release
L_H3_NotRequested:
    h_bufferspeciesname 1, SPECIES_BELLOSSOM        // bufferspeciesname 0, VAR_0x8009
    h_msgbox T_NOTMON                               // That's no Bellossom.
    VMJump L_H3_Release
L_H3_Completed:
    h_msgbox T_FRIENDS                              // Since we traded, you and me, we're friends, aren't we?
L_H3_Release:
    WorkSetConst H3_CHECK, 0
    WorkSetConst H3_OK, 0
    WorkSetConst H3_SLOT, 0
    h_release
    .balign 4, 0
